const fmt=n=>Math.round(n).toLocaleString("en-IN");
function vipFor(w){let t=cfg().vip[0];for(const v of cfg().vip)if(w>=v.wagered)t=v;return t;}
/* Max stake is bounded by the Admin-configured ceiling and the level curve. */
function maxStake(){const cap=Math.max(10,Math.round(cfg().stakeMax||1000));return Math.min(cap,100+S.level*100);}
function toast(m,ty=""){const t=document.createElement("div");t.className="toast "+ty;t.innerHTML=m;$("toasts").appendChild(t);setTimeout(()=>{t.style.opacity=0;t.style.transition=".3s";setTimeout(()=>t.remove(),300)},3400);}
function addFeed(m,jp=false){const d=new Date();S.feed.unshift({t:d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'}),msg:m,jp});if(S.feed.length>60)S.feed.pop();}
function pushHistory(type,row){S.histories=S.histories||{};S.histories[type]=S.histories[type]||[];S.histories[type].unshift({t:Date.now(),...row});if(S.histories[type].length>200)S.histories[type].length=200;}
function recordPlayerMetrics({stake=0,payout=0,fee=0,source='game',result=''}){const st=S.stats;st.biggestStake=Math.max(st.biggestStake||0,stake);st.bestWin=Math.max(st.bestWin||0,payout-stake);st.lifetimeWagered=(st.lifetimeWagered||0)+Math.max(0,stake);st.totalPayout=(st.totalPayout||0)+Math.max(0,payout);st.maxPayout=Math.max(st.maxPayout||0,payout);st.feesPaid=(st.feesPaid||0)+Math.max(0,fee);if(result==='DRAW')st.draws=(st.draws||0)+1;if(result==='CARRY')st.carries=(st.carries||0)+1;if(source==='catalog')st.catalogGames=(st.catalogGames||0)+1;if(source==='series')st.seriesPlayed=(st.seriesPlayed||0)+1;if(source==='tournament')st.tournamentEntries=(st.tournamentEntries||0)+1;if(source==='friend')st.friendGames=(st.friendGames||0)+1;if(source==='room')st.roomGames=(st.roomGames||0)+1;if(source==='clan')st.clanGames=(st.clanGames||0)+1;if(source==='arcade')st.arcadePlays=(st.arcadePlays||0)+1;}
function beep(f,dur,ty="sine",v=.07,when=0){
  if(!S.settings.sound)return;try{if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();
    const o=audioCtx.createOscillator(),g=audioCtx.createGain();const wav=COS.sounds.find(s=>s.id===S.equipped.sound)||COS.sounds[0];
    o.type=wav.wave[when?1:0]||ty;o.frequency.value=f;o.connect(g);g.connect(audioCtx.destination);
    const t0=audioCtx.currentTime+when;g.gain.setValueAtTime(v,t0);g.gain.exponentialRampToValueAtTime(.0001,t0+dur);o.start(t0);o.stop(t0+dur);
  }catch(e){}
}
function sfxFlip(){beep(880,.12,"triangle",.06,0);beep(660,.16,"triangle",.05,.12);beep(440,.22,"sine",.045,.28);}
function sfxWin(){[523,659,784,1047].forEach((f,i)=>beep(f,.16,"sine",.06,i*.08));}
function sfxLose(){beep(300,.22,"sawtooth",.045);}
function sfxJp(){[523,659,784,1047,1319,1568].forEach((f,i)=>beep(f,.2,"square",.05,i*.07));}
function confettiFx(){
  const fx=COS.fx.find(f=>f.id===S.equipped.fx)||COS.fx[0];
  for(let i=0;i<28;i++){const c=document.createElement("div");c.className="confetti";c.textContent=fx.emojis[i%fx.emojis.length];
    c.style.left=Math.random()*100+"vw";c.style.animationDuration=(1.8+Math.random()*1.8)+"s";c.style.fontSize=(16+Math.random()*16)+"px";
    document.body.appendChild(c);setTimeout(()=>c.remove(),3800);}
}
