function featureIntro(group,id){const x=FEATURE_INFO[group][id];return `<div class="feature-intro"><div><span class="feature-code">${x.angle.toUpperCase()}</span><h2>${x.title}</h2><p>${x.desc}</p></div><div class="feature-meta"><span class="feature-pill live">● LIVE DEMO</span><span class="feature-pill">${x.effort}</span><span class="feature-pill revenue">${x.angle}</span></div></div><div class="feature-points">${x.points.map(p=>`<div class="feature-point"><b>${p[0]}</b>${p[1]}</div>`).join('')}</div>`;}
function weekKey(){const d=new Date(),y=new Date(Date.UTC(d.getUTCFullYear(),0,1)),w=Math.ceil((((d-y)/86400000)+y.getUTCDay()+1)/7);return `${d.getUTCFullYear()}-W${String(w).padStart(2,'0')}`;}
function ensureFeaturePeriods(){
  const month=new Date().toISOString().slice(0,7),week=weekKey(),bp=S.engagement.battlePass,wk=S.engagement.weekly;
  if(bp.month!==month)S.engagement.battlePass={month,xp:0,premium:false,claimedFree:[],claimedPremium:[]};
  if(wk.key!==week)S.engagement.weekly={key:week,wins:0,games:0,gameTypes:{},bestStreak:0,claimed:[]};
  const rf=S.featureGames.raffle;if(rf.week!==week)S.featureGames.raffle={week,playerTickets:0,botTickets:80+Math.floor(Math.random()*80),pool:0,lastWinner:""};
}
function subscriptionActive(){return S.economyPlus.subscription.expires>Date.now();}
function subscriptionQuestMult(){return subscriptionActive()&&['pro','elite'].includes(S.economyPlus.subscription.tier)?2:1;}
function xpMultiplier(){return (Date.now()<S.economyPlus.boosters.xpUntil?2:1)*(1+(S.engagement.prestige||0)*.05);}
function effectiveRakeback(rate){return Math.min(25,rate+(Date.now()<S.economyPlus.boosters.rakeUntil?5:0));}
function applyLevelUps(){
  const target=Math.floor(Math.sqrt(S.xp/60))+1;if(target<=S.level)return 0;let total=0;
  for(let lv=S.level+1;lv<=target;lv++)total+=+(cfg().levelRewards[lv]??lv*50);
  S.wallet.bonus+=total;cfg().taps+=total;const from=S.level;S.level=target;S.levelMilestones=S.levelMilestones||{};
  const milestones={30:'rare',40:'epic',50:'legendary'},gifts=[];
  Object.entries(milestones).forEach(([lv,rarity])=>{if(from<+lv&&target>=+lv&&!S.levelMilestones[lv]){const gift=randomShopItem(rarity);grantShopItem(gift);S.levelMilestones[lv]=gift?.it?.name||'cosmetic';gifts.push(`Level ${lv}: ${S.levelMilestones[lv]}`);}});
  toast(`⭐ Level ${target}! +${fmt(total)} BONUS${gifts.length?' · '+gifts.join(' · '):''}`,gifts.length?'jp':'ok');addFeed(`⭐ <b>You</b> advanced from level ${from} to ${target} · +${fmt(total)} BONUS`);checkProgressAchievements();return total;
}
function awardXp(amount){ensureFeaturePeriods();const gain=Math.round(amount*xpMultiplier());S.xp+=gain;S.engagement.battlePass.xp+=gain;applyLevelUps();return gain;}
function recordEngagement(gameId,won){ensureFeaturePeriods();const w=S.engagement.weekly;w.games++;if(won)w.wins++;w.gameTypes[gameId||'game']=true;w.bestStreak=Math.max(w.bestStreak,S.streak||0);}
function skillTier(games,wins){if(games<10)return 'Rookie';const wr=wins/Math.max(1,games)*100;return wr<45?'Bronze':wr<55?'Silver':wr<65?'Gold':'Elite';}
function playerSkillTier(){return skillTier(S.stats.games,S.stats.wins);}
function filterSkillBots(pool){pool=readyBotPool(pool,'Required first top-up before skill matchmaking');if(!S.engagement.skillOnly)return pool;const t=playerSkillTier(),same=pool.filter(b=>skillTier(b.games||0,b.wins||0)===t);return same.length?same:pool;}
function spendMain(amount,label){
  amount=coin(amount);
  if(amount<=0||coin(S.wallet.main)<amount){toast('Not enough MAIN.', 'err');return false;}
  // Debit through the shared money module: validated, atomic and ledgered.
  const res=debitWallet({main:amount},label||'feature spend');
  if(!res.ok){toast(res.error||'Spend rejected.', 'err');return false;}
  const h=cfg().house;h.shop=add(h.shop||0,amount);h.netRevenue=add(h.netRevenue||0,amount);h.sinks=add(h.sinks||0,amount);
  ledger('feature-spend',-amount,label);return true;
}
function featureTabs(hub,items){return `<div class="hub-tabs">${items.map(x=>`<button class="hub-tab ${HUB[hub]===x[0]?'active':''}" data-hub="${hub}" data-hubtab="${x[0]}">${x[1]}</button>`).join('')}</div>`;}
function featureHeader(title,desc){return `<div class="card" style="margin-bottom:14px"><h3>${title}</h3><p class="muted">${desc}</p></div>`;}
function friendOptions(){return S.social.friends.map(n=>`<option value="${n}">${n}</option>`).join('');}
function paidOwnedItems(){const out=[];for(const cat of ['skins','avatars','frames','colours','fx','themes','sounds','emojis'])for(const id of S.owned[cat]||[]){const it=(COS[cat]||[]).find(x=>x.id===id);if(it&&it.price>0)out.push({cat,id,name:it.name||it.ch});}return out;}
function randomShopItem(min='common'){const rank={common:1,uncommon:2,rare:3,epic:4,legendary:5,mythic:6},all=[];for(const cat of ['skins','avatars','frames','colours','fx','themes','sounds','emojis'])for(const it of COS[cat]||[])if(it.price>0&&!it.vipOnly&&(rank[it.rarity]||0)>=(rank[min]||1))all.push({cat,it});return all[Math.floor(Math.random()*all.length)];}
function grantShopItem(x){if(!x)return;grantOwned(x.cat,x.it.id);}
/* Event Calendar (LIVE1 demo): one timezone-aware schedule of every
   scheduled opportunity — trivia, raffle draw, season end, VIP reset,
   live auto-tournaments and active campaigns — with reminders. */
function buildEventSchedule(){
  const now=Date.now(),events=[],today=new Date();
  const endOfDay=new Date(today);endOfDay.setHours(23,59,59,999);
  events.push({id:'trivia-'+today.toDateString(),icon:'❓',title:'Daily Trivia',sub:'One 3× question refreshes at midnight',ends:endOfDay.getTime(),live:false});
  const raffleEnd=(()=>{const d=new Date(now);d.setHours(20,0,0,0);let add=(7-d.getDay())%7;if(add===0&&d.getTime()<=now)add=7;d.setDate(d.getDate()+add);return d;})();
  events.push({id:'raffle-'+weekKey(),icon:'🎫',title:'Weekly Raffle Draw',sub:'Winner takes 80% of the ticket pool · house 20%',ends:raffleEnd.getTime(),live:false});
  events.push({id:'tourney-live',icon:'🏟',title:'Auto Tournaments',sub:'Bots open brackets continuously — join from Cups & Tournaments',ends:0,live:true});
  const c=typeof cfg!=='undefined'?cfg():{seasonEnds:0,promotions:[]};
  if(c.seasonEnds)events.push({id:'season-'+(c.seasonNumber||1),icon:'🏁',title:'Season '+(c.seasonNumber||1)+' ends',sub:'Champion 500 🪙 + title · runner-up 250 🪙',ends:c.seasonEnds,live:false});
  const nm=new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth()+1,1,0,0,0));
  events.push({id:'vip-reset-'+nm.toISOString().slice(0,7),icon:'💎',title:'VIP month resets',sub:'Monthly wagered counters reset · tier perks refresh',ends:nm.getTime(),live:false});
  (c.promotions||[]).filter(p=>p.on&&p.end&&p.end>now).forEach(p=>events.push({id:'promo-'+p.id,icon:'🎁',title:(p.type||'promo').toUpperCase()+' campaign',sub:p.type==='deposit'?fmt(p.amount)+'% on next top-up':fmt(p.amount)+' coins · claim from Safety & Services → Offers',ends:p.end,live:false}));
  return events.sort((a,b)=>(a.ends||Infinity)-(b.ends||Infinity));
}
function renderCommunityHub(){ensureFeaturePeriods();const tabs=[['friends','👥 Friends'],['rooms','🔒 Private Rooms'],['profile','🪪 Profile'],['spectate','👁 Spectator'],['gifts','🎁 Gifting'],['chat','💬 Chat'],['clans','🛡 Clans'],['events','🗓 Events']],f=HUB.community;let body='';
  if(f==='friends'){const names=S.bots.slice(0,30),requests=S.social.friendRequests||[];body=`<div class="card"><h3>👥 Friend List & Buddy System</h3><p class="muted">Bots now send friend requests, form their own connections, chat, and remain available for direct challenges.</p>${requests.length?`<div class="catalog-note" style="margin-bottom:12px"><b>Incoming bot requests (${requests.length})</b>${requests.slice(0,8).map(n=>`<div class="friend-row"><span>🙋</span><span class="grow"><b>${n}</b> wants to connect</span><button class="btn btn-sm btn-primary" data-feature="friend-accept" data-name="${n}">Accept</button><button class="btn btn-sm btn-ghost" data-feature="friend-decline" data-name="${n}">Decline</button></div>`).join('')}</div>`:''}<div class="grid2"><div><h4 class="section-title">Friends (${S.social.friends.length})</h4>${S.social.friends.map(n=>{const b=botByName(n);return `<div class="friend-row"><span class="online-dot"></span><span class="grow"><b>${n}</b> ${b?.flag||''} · ${skillTier(b?.games||0,b?.wins||0)}</span><button class="btn btn-sm btn-primary" data-feature="challenge" data-name="${n}">Challenge</button><button class="btn btn-sm btn-danger" data-feature="friend-remove" data-name="${n}">Remove</button></div>`}).join('')||'<div class="empty">Accept a request or add a buddy.</div>'}</div><div><h4 class="section-title">Online players (${S.bots.length})</h4>${names.filter(b=>!S.social.friends.includes(b.name)).map(b=>`<div class="friend-row"><span class="online-dot"></span><span class="grow">${b.avi} <b>${b.name}</b> ${b.flag} · Lv${b.level}</span><button class="btn btn-sm btn-ghost" data-feature="friend-add" data-name="${b.name}">Add</button></div>`).join('')}</div></div></div>`;}
  else if(f==='rooms'){body=`<div class="card"><h3>🔒 Invite-only Private Rooms</h3><div class="grid3 room-form"><div><label>Room name</label><input id="roomName" value="My VIP Room"/><label>Game</label><select id="roomGame"><option>Coin Toss</option>${GAMES.map(g=>`<option value="${g.id}">${g.name}</option>`).join('')}</select></div><div><label>Minimum stake</label><input id="roomMin" type="number" value="50"/><label>Maximum stake</label><input id="roomMax" type="number" value="200"/></div><div><label>Access</label><select id="roomAccess"><option value="friends">Friends only</option><option value="invite">Invite code</option></select><button class="btn btn-primary" data-feature="room-create" style="margin-top:18px">Create room</button></div></div><div class="section-title">Your rooms</div>${S.social.privateRooms.map(r=>`<div class="friend-row"><span>🔒</span><span class="grow"><b>${r.name}</b> · ${r.game} · ${r.min}-${r.max} · ${r.access} · code ${r.code}</span><button class="btn btn-sm btn-primary" data-feature="room-start" data-id="${r.id}">Start with bot</button><button class="btn btn-sm btn-ghost" data-feature="room-details" data-id="${r.id}">Details</button><button class="btn btn-sm btn-danger" data-feature="room-delete" data-id="${r.id}">Delete</button></div>`).join('')||'<div class="empty">No private rooms.</div>'}</div>`;}
  else if(f==='profile'){const wr=S.stats.games?Math.round(S.stats.wins/S.stats.games*100):0,owned=Object.values(S.owned).reduce((a,x)=>a+x.length,0);body=`<div class="grid2"><div class="card"><h3>🪪 Public Player Profile</h3><div class="profile-head"><span class="ph-avi">${playerAviHTML(52)}</span><div><div class="ph-name">You ${playerFlag()}</div><div class="ph-title">${currentVipEntitlements().title||vipFor(S.monthWagered).name+' VIP'} · ${playerSkillTier()} skill</div></div></div><div class="prof-stat"><div class="ps"><div class="v">${S.stats.games}</div><div class="k">Games</div></div><div class="ps"><div class="v">${wr}%</div><div class="k">Win rate</div></div><div class="ps"><div class="v">${S.stats.net>=0?'+':''}${fmt(S.stats.net)}</div><div class="k">Net</div></div><div class="ps"><div class="v">${S.level}</div><div class="k">Level</div></div><div class="ps"><div class="v">${owned}</div><div class="k">Cosmetics</div></div><div class="ps"><div class="v">${Object.keys(S.achievements).length}</div><div class="k">Achievements</div></div></div><div class="section-title">Career win-rate graph</div><div class="bias-bar"><div class="h" style="width:${wr}%">WIN ${wr}%</div><div class="t" style="width:${100-wr}%">OTHER ${100-wr}%</div></div></div><div class="card"><h3>🏅 Showcase</h3><div class="ach-grid">${ACHIEVEMENTS.filter(a=>S.achievements[a.id]).slice(0,12).map(a=>`<div class="ach unlocked"><div class="ai">${a.icon}</div><div><div class="an">${a.name}</div><div class="ad">${a.desc}</div></div></div>`).join('')||'<div class="empty">No achievements yet.</div>'}</div><div class="section-title">Recent games</div>${S.games.slice(0,6).map(g=>`<div class="kv-row"><span>${g.game||'Coin Toss'} vs ${g.oppName}</span><b style="color:${g.delta>=0?'var(--green)':'var(--red)'}">${g.delta>=0?'+':''}${fmt(g.delta)}</b></div>`).join('')}</div></div>`;}
  else if(f==='spectate'){const live=[...(S.catalogLog||[])].slice(0,16);body=`<div class="card"><h3>👁 Live Spectator Mode</h3><p class="muted">Watch recent bot and player matches with pot, picks, cosmetics, result and proof detail.</p>${live.map((x,i)=>`<div class="friend-row"><span class="spectate-live">🔴</span><span class="grow"><b>${x.game}</b> · ${x.playerA} vs ${x.playerB} · pot ${fmt(x.stake*2)}</span><button class="btn btn-sm btn-primary" data-feature="spectate" data-index="${i}">Watch</button></div>`).join('')||'<div class="empty">Live matches appear as bots play.</div>'}</div>`;}
  else if(f==='gifts'){const items=paidOwnedItems();body=`<div class="grid2"><div class="card"><h3>🎁 Gift Coins</h3><label>Friend</label><select id="giftFriend">${friendOptions()}</select><label>MAIN coins</label><input id="giftCoins" type="number" value="50" min="10"/><button class="btn btn-primary" data-feature="gift-coins" style="margin-top:10px">Send coins</button><p class="muted">MAIN only · transfer fee applies · shared daily transfer cap.</p></div><div class="card"><h3>🎨 Gift Cosmetic</h3><label>Friend</label><select id="giftCosFriend">${friendOptions()}</select><label>Owned paid item</label><select id="giftItem">${items.map(x=>`<option value="${x.cat}:${x.id}">${x.name} (${x.cat})</option>`).join('')}</select><button class="btn btn-primary" data-feature="gift-cosmetic" style="margin-top:10px">Gift cosmetic</button></div></div><div class="card" style="margin-top:14px"><h3>Gift history</h3>${S.social.gifts.slice(0,20).map(x=>`<div class="kv-row"><span>${new Date(x.t).toLocaleTimeString()} · ${x.to}</span><b>${x.item}</b></div>`).join('')||'<div class="empty">No gifts yet.</div>'}</div>`;}
  else if(f==='chat'){body=`<div class="grid2"><div class="card"><h3>💬 Lobby Chat</h3><div class="feed" style="height:300px">${S.social.chat.slice(-40).map(m=>`<div class="chat-row"><span>${m.from==='You'?'🫵':'🤖'}</span><span class="grow"><b>${m.from}</b><br>${m.text}</span><span class="muted">${new Date(m.t).toLocaleTimeString()}</span></div>`).join('')||'<div class="empty">Start the conversation.</div>'}</div><div class="react-bar" style="margin:8px 0">${[...FREE_EMOJIS,...COS.emojis.filter(x=>S.owned.emojis.includes(x.id)).map(x=>x.ch)].map(x=>`<button class="react-btn" data-feature="chat-emoji" data-emoji="${x}">${x}</button>`).join('')}</div><div class="game-row"><input id="chatText" maxlength="100" placeholder="Message or premium emoji…"/><button class="btn btn-primary" data-feature="chat-send">Send</button></div></div><div class="card"><h3>Mute & Block</h3>${S.social.friends.map(n=>`<div class="friend-row"><span class="grow">${n}</span><button class="btn btn-sm btn-ghost" data-feature="mute" data-name="${n}">${S.social.muted.includes(n)?'Unmute':'Mute'}</button><button class="btn btn-sm btn-danger" data-feature="block" data-name="${n}">${S.social.blocked.includes(n)?'Unblock':'Block'}</button></div>`).join('')||'<div class="empty">Add friends to manage chat.</div>'}</div></div>`;}
  else if(f==='events'){const now=Date.now(),sch=buildEventSchedule(),rem=S.social.eventReminders=S.social.eventReminders||{};body=`<div class="card"><h3>🗓 Event Calendar <span class="muted" style="margin-left:auto;font-weight:400">local + UTC · reminders persist</span></h3><p class="muted">Every scheduled opportunity in one timezone-aware place. Reminders persist per event id — live events, daily trivia, weekly raffles, season resets and active campaigns all appear here in one timezone-aware place (local + UTC).</p>${sch.map(ev=>{const left=(ev.ends||0)-now,mm=Math.max(0,Math.floor(left/60000)),days=Math.floor(mm/1440),hrs=Math.floor(mm%1440/60),min=mm%60;const cd=ev.live?'<span class="tag on">LIVE</span>':(ev.ends&&left<=0)?'<span class="tag">done</span>':`<b class="event-cd">⏳ ${days?days+'d ':''}${hrs}h ${min}m</b>`;return `<div class="friend-row"><span style="font-size:18px">${ev.icon}</span><span class="grow"><b>${ev.title}</b><br><span class="muted">${ev.sub}${ev.ends?' · '+new Date(ev.ends).toLocaleString()+' · UTC '+new Date(ev.ends).toISOString().slice(5,16).replace('T',' '):''}</span></span>${cd}<button class="btn btn-sm ${rem[ev.id]?'btn-primary':'btn-ghost'}" data-feature="event-remind" data-id="${ev.id}">${rem[ev.id]?'🔔 On':'🔕 Off'}</button></div>`;}).join('')}</div>`;}
  else {const c=S.social.clan;body=!c?`<div class="card"><h3>🛡 Create a Clan</h3><div class="grid3"><div><label>Clan name</label><input id="clanName" value="Coin Guardians"/></div><div><label>Tag</label><input id="clanTag" value="CG" maxlength="5"/></div><div><button class="btn btn-primary" data-feature="clan-create" style="margin-top:18px">Create clan</button></div></div></div>`:`<div class="grid2"><div class="card"><h3>🛡 [${c.tag}] ${c.name}</h3><div class="kv-row"><span>Team score</span><b>${fmt(S.social.clanScore)}</b></div><div class="section-title">Roster</div><div class="friend-row"><span>🫵</span><b class="grow">You · Leader</b></div>${c.members.map(n=>`<div class="friend-row"><span>🤖</span><span class="grow">${n}</span><button class="btn btn-sm btn-danger" data-feature="clan-remove" data-name="${n}">Remove</button></div>`).join('')}</div><div class="card"><h3>Team Actions</h3><label>Add friend</label><select id="clanFriend">${S.social.friends.filter(n=>!c.members.includes(n)).map(n=>`<option>${n}</option>`).join('')}</select><button class="btn btn-ghost" data-feature="clan-add" style="margin-top:8px">Add member</button><button class="btn btn-primary" data-feature="clan-match" style="margin-top:8px">⚔ Team vs Team match</button><button class="btn btn-purple" data-feature="clan-tourney" style="margin-top:8px">🏟 Clan tournament</button><button class="btn btn-danger" data-feature="clan-leave" style="margin-top:8px">Disband</button><div class="section-title">Clan leaderboard</div>${[['Flip Titans',8200],['Hash Heroes',6100],[c.name,S.social.clanScore],['Lucky Guild',2800]].sort((a,b)=>b[1]-a[1]).map((x,i)=>`<div class="kv-row"><span>#${i+1} [${x[0]===c.name?c.tag:'BOT'}] ${x[0]}</span><b>${fmt(x[1])}</b></div>`).join('')}<div class="section-title">Clan game history</div>${(S.histories.clanGames||[]).slice(0,8).map(x=>`<div class="kv-row"><span>${new Date(x.t).toLocaleTimeString()} · ${x.title}</span><b>${x.result}</b></div>`).join('')||'<div class="empty">No clan games yet.</div>'}</div></div>`;}
  const botSocial=(S.botActivity?.socialLog||[]).slice(0,10);body+=`<div class="card" style="margin-top:14px"><h3>🤖 Live bot social activity</h3>${botSocial.map(x=>`<div class="friend-row"><span>${x.icon||'🤖'}</span><span class="grow"><b>${x.area}</b><br><span class="muted">${x.detail}</span></span><span class="muted">${new Date(x.t).toLocaleTimeString()}</span></div>`).join('')||'<div class="empty">Bot social activity starts automatically.</div>'}</div>`;
  $("communityHub").innerHTML=featureHeader('🤝 Social & Community','Friends, rooms, profiles, spectators, gifting, chat, clans and the timezone-aware event calendar are simulated with an autonomous bot population.')+featureTabs('community',[['friends','Friends'],['rooms','Rooms'],['profile','Profiles'],['spectate','Spectator'],['gifts','Gifting'],['chat','Chat'],['clans','Clans'],['events','Events']])+body;
}
