async function playRoomCatalog(room,botName,stake){if(busy)return;const g=GAMES.find(x=>x.id===room.game),bot=botByName(botName);if(!g||!bot)return;stake=Math.round(stake);try{checkGuards(stake);}catch(e){toast(e.message,'err');return;}let split;try{split=escrow(stake);}catch(e){toast(e.message,'err');return;}if(bot.balance<stake){refund(split);return;}bot.balance-=stake;const pick=String(catalogDefaultPick(g)),botPick=String(catalogBotPick(g,pick)),bet={id:'room'+S.gid++,owner:'you',name:'You',kind:'catalog',catalogGame:g.id,gameName:g.name,pick,stake,split,source:'room',roomId:room.id,roomName:room.name};busy=true;await settleCatalogBet(g,bet,bot,botPick);}
async function directFriendChallenge(name,stake=50,context={}){if(busy)return;const bot=botByName(name);stake=Math.round(+stake||50);if(!bot||bot.balance<stake){toast('Friend cannot cover that challenge.','err');return;}try{checkGuards(stake);}catch(e){toast(e.message,'err');return;}let split;try{split=escrow(stake);}catch(e){toast(e.message,'err');return;}bot.balance-=stake;const source=context.source||'friend',p={owner:'you',name:'You',side:'HEADS',stake,split,kind:source},b={owner:bot.name,name:bot.name,flag:bot.flag,side:'TAILS',stake};addFeed(`${source==='room'?'🔒':'🤝'} <b>You</b> challenged <b>${bot.name}</b>${context.roomName?' in '+context.roomName:''}`);await settleFlip(p,b,bot,{source,...context});}
