async function playFeatureP2P(kind,stake){
  if(busy)return;stake=Math.round(+stake);try{checkGuards(stake);}catch(e){toast(e.message,'err');return;}let split;try{split=escrow(stake);}catch(e){toast(e.message,'err');return;}
  const pool=filterSkillBots(S.bots.filter(b=>ensureBotFirstTopup(b,'Required first top-up before activity')&&b.balance>=stake)),bot=pool[Math.floor(Math.random()*pool.length)];if(!bot){refund(split);return;}bot.balance-=stake;busy=true;
  try{const g={id:'feature-'+kind},fair=await catalogFairOutcome(g,stake,'PLAYER','BOT'),bytes=fair.bytes,pot=stake*2,fee=Math.round(pot*cfg().feePct/100),payout=pot-fee;let win=false,draw=false,detail='';
    if(kind==='ladder'){const rung=x=>x%6===0?0:x%6,a=rung(bytes[0]),b=rung(bytes[1]);win=a>b;draw=a===b;detail=`You ${a?'rung '+a:'BUST'} · ${bot.name} ${b?'rung '+b:'BUST'}`;}
    else{const rank=x=>x%13+2,n=x=>x<=10?x:['J','Q','K','A'][x-11];let i=0,a=rank(bytes[i++]),b=rank(bytes[i++]);while(a===b&&i<bytes.length-1){a=rank(bytes[i++]);b=rank(bytes[i++]);}win=a>b;draw=a===b;detail=`You ${n(a)} · ${bot.name} ${n(b)}${i>2?' after WAR':''}`;}
    let delta;if(draw){const pp=Math.floor(payout/2);S.wallet.main+=pp;bot.balance+=payout-pp;delta=pp-stake;}else if(win){S.wallet.main+=payout;delta=payout-stake;}else{bot.balance+=payout;delta=-stake;}
    S.stats.games++;if(win)S.stats.wins++;else if(!draw)S.stats.losses++;S.stats.net+=delta;S.monthWagered+=stake;awardXp(stake);recordEngagement(kind,win);cfg().house.catalogFees=(cfg().house.catalogFees||0)+fee;cfg().house.netRevenue+=fee;cfg().sinks+=fee;const title=kind==='ladder'?'Multiplier Ladder P2P':'War Card Game',result=draw?'DRAW':win?'WIN':'LOSE',paid=draw?Math.floor(payout/2):win?payout:0;S.games.unshift({id:S.gid++,t:Date.now(),game:title,result,stake,fee,payout:paid,oppName:bot.name,oppFlag:bot.flag,winner:draw?'draw':win?'you':'opp',delta,verified:true,resultText:detail});recordPlayerMetrics({stake,payout:paid,fee,source:'arcade',result});pushHistory('arcade',{title,detail:`${detail} · stake ${stake} · fee ${fee}`,result,amount:delta,payout:paid});S.featureGames[kind].unshift({t:Date.now(),stake,result:draw?'DRAW':win?'WIN':'LOSE',detail});if(S.featureGames[kind].length>50)S.featureGames[kind].length=50;toast(`${detail} · ${draw?'DRAW':win?'WIN':'LOSE'} ${delta>=0?'+':''}${delta}`,win?'ok':draw?'':'err');
  }catch(e){refund(split);bot.balance+=stake;}finally{busy=false;render();renderNewGamesHub();}
}
