  const widgetOrder=(S.settings.dashboardWidgets||[]).map(id=>DASHBOARD_WIDGETS.find(x=>x.id===id)).filter(Boolean);
  const kpiEl=$("homeKpis"),kpiSig=widgetOrder.map(x=>x.id).join("|");
