function currentNavTab(){return document.querySelector('#tabs .tab.active')?.dataset.tab||'';}
export function applyNavGroups(){
  const nav=$("tabs");if(!nav||!S)return;
  const searching=!!(($("playerNavSearch")||{}).value||"").trim();
  nav.classList.toggle("searching",searching);
  const groups=S.settings.navGroups=S.settings.navGroups||{};
  nav.querySelectorAll(".nav-group").forEach(g=>{
    const collapsed=!!groups[g.dataset.group]&&!searching;
    g.classList.toggle("collapsed",collapsed);
    const head=g.querySelector(".nav-group-head");if(head)head.setAttribute("aria-expanded",String(!collapsed));
  });
}
export function recordRecentTab(tab){if(!tab)return;const r=S.settings.recentTabs=S.settings.recentTabs||[];const i=r.indexOf(tab);if(i>=0)r.splice(i,1);r.unshift(tab);if(r.length>8)r.length=8;renderNavRecent();save();}
